// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        address ownerBefore = c.owner();
        vm.prank(actor);
        try c.setOwner(newOwner) {
            // If caller was not the owner, owner must be unchanged.
            assertTrue(
                actor == ownerBefore ? c.owner() == newOwner : c.owner() == ownerBefore,
                "non-owner must not be able to change the owner"
            );
        } catch {
            // Reverting is only acceptable for non-owners.
            assertTrue(actor != ownerBefore, "owner should be able to setOwner");
        }
    }
}
